grant create on schema api,app_private to git_tutor_commands;
create table app_private.learner_link_reviews(id uuid primary key default gen_random_uuid(),inquiry_id uuid not null,learner_id uuid not null,version integer not null,active boolean not null,evidence_file_id uuid not null references app_private.files(id),reason text not null,actor_id uuid not null references app_private.accounts(id),created_at timestamptz not null default now(),foreign key(inquiry_id,learner_id)references app_private.learner_links(inquiry_id,learner_id),unique(inquiry_id,learner_id,version));
alter table app_private.learner_link_reviews enable row level security;
create policy commands_access on app_private.learner_link_reviews to git_tutor_commands using(true)with check(true);
revoke all on app_private.learner_link_reviews from public,anon,authenticated,service_role,git_tutor_worker;
grant select,insert on app_private.learner_link_reviews to git_tutor_commands;
create trigger immutable_row before update or delete on app_private.learner_link_reviews for each row execute function app_private.reject_immutable_change();
alter table app_private.learner_attribution_revisions alter column first_inquiry_id drop not null;
create function app_private.analytics_link_active(p_inquiry uuid,p_learner uuid,p_as_of timestamptz)returns boolean language sql stable security definer set search_path='' as $$
 select coalesce((select r.active from app_private.learner_link_reviews r where r.inquiry_id=p_inquiry and r.learner_id=p_learner and r.created_at<=p_as_of order by r.version desc limit 1),(select l.basis<>'authenticated_self'or exists(select 1 from app_private.support_account_links s join app_private.lead_inquiries i on i.conversation_id=s.conversation_id where i.id=p_inquiry and s.learner_id=p_learner and s.created_at<=p_as_of)from app_private.learner_links l where l.inquiry_id=p_inquiry and l.learner_id=p_learner and l.created_at<=p_as_of),false)
$$;
alter function app_private.analytics_link_active(uuid,uuid,timestamptz)owner to git_tutor_commands;
create or replace function app_private.analytics_refresh_attribution(p_learner uuid)returns void language plpgsql security definer set search_path='' as $$declare winner record;previous app_private.learner_attribution_revisions%rowtype;begin
 perform 1 from app_private.learners where id=p_learner for update;
 select i.id,coalesce(r.attribution,'unknown')attribution,r.campaign_id into winner from app_private.learner_links l join app_private.lead_inquiries i on i.id=l.inquiry_id left join lateral(select a.attribution,a.campaign_id from app_private.attribution_revisions a where a.inquiry_id=i.id order by a.version desc limit 1)r on true where l.learner_id=p_learner and app_private.analytics_link_active(l.inquiry_id,l.learner_id,now()) order by i.observed_at,i.id limit 1;

 select * into previous from app_private.learner_attribution_revisions where learner_id=p_learner order by created_at desc,id desc limit 1;
 if (previous.id is null and winner.id is not null) or(previous.first_inquiry_id,previous.attribution,previous.campaign_id)is distinct from(winner.id,winner.attribution,winner.campaign_id)then insert into app_private.learner_attribution_revisions(learner_id,first_inquiry_id,attribution,campaign_id,previous_revision_id)values(p_learner,winner.id,coalesce(winner.attribution,'unknown'),winner.campaign_id,previous.id);end if;
end$$;
create or replace function app_private.analytics_source_hook()returns trigger language plpgsql security definer set search_path='' as $$declare c app_private.conversations%rowtype;l uuid;inquiry uuid;begin
 if tg_table_name='enrollments'then perform app_private.analytics_record_inquiry('website_booking',new.id,null,new.booker_account_id,new.created_at,null,new.learner_id);
 elsif tg_table_name='support_messages'then
  if new.author<>'customer'then return new;end if;select * into c from app_private.conversations where id=new.conversation_id;
  l:=null;
  inquiry:=app_private.analytics_record_inquiry(case when c.channel='whatsapp'then'whatsapp'else'support'end,new.id,c.id,c.account_id,new.created_at,c.source_token,l);
  insert into app_private.learner_links(inquiry_id,learner_id,basis,actor_id)select inquiry,s.learner_id,'verified_support_link',s.account_id from app_private.support_account_links s where s.conversation_id=c.id and s.learner_id is not null on conflict do nothing;
 elsif tg_table_name='support_account_links'then
  if new.learner_id is not null then insert into app_private.learner_links(inquiry_id,learner_id,basis,actor_id)select i.id,new.learner_id,'verified_support_link',new.account_id from app_private.lead_inquiries i where i.conversation_id=new.conversation_id on conflict do nothing;perform app_private.analytics_refresh_attribution(new.learner_id);end if;
 end if;return new;
end$$;
create or replace function app_private.analytics_attendance(p_as_of timestamptz)returns table(learner_id uuid,occurrence_id uuid,actual_start_at timestamptz,actual_end_at timestamptz,tutor_id uuid,attendance text,attended_seconds bigint)language sql stable security definer set search_path='' as $$
 select e.learner_id,c.occurrence_id,coalesce((am.new_facts->>'actual_start_at')::timestamptz,a.actual_start_at),coalesce((am.new_facts->>'actual_end_at')::timestamptz,a.actual_end_at),ta.tutor_id,fact->>'attendance',(fact->>'attended_seconds')::bigint
 from app_private.completions c join app_private.occurrences approved_occurrence on approved_occurrence.id=c.occurrence_id and approved_occurrence.state='completed' join app_private.completion_approvals approved on approved.completion_id=c.id and approved.approved_at<=p_as_of join app_private.attendance_snapshots a on a.id=c.attendance_id join app_private.tutor_assignments ta on ta.id=c.assignment_id
 left join lateral(select x.new_facts from app_private.completion_amendments x where x.completion_id=c.id and x.created_at<=p_as_of order by x.version desc limit 1)am on true
 cross join lateral jsonb_array_elements(coalesce(am.new_facts->'attendance_corrections',a.entries))fact join app_private.enrollments e on e.id=(fact->>'enrollment_id')::uuid
 where coalesce((am.new_facts->>'actual_end_at')::timestamptz,a.actual_end_at)<=p_as_of
$$;
create or replace function app_private.analytics_cohort_rows(p_from date,p_to date,p_as_of timestamptz,p_days integer,p_campaign uuid,p_source text,p_format text,p_subject uuid)returns setof jsonb language sql stable security definer set search_path='' as $$
 with first_touch as(
  select distinct on(l.learner_id) l.learner_id,i.*,coalesce(r.attribution,'unknown')attribution,r.campaign_id
  from app_private.learner_links l join app_private.lead_inquiries i on i.id=l.inquiry_id
  left join lateral(select a.attribution,a.campaign_id from app_private.attribution_revisions a where a.inquiry_id=i.id and a.created_at<=p_as_of order by a.version desc limit 1)r on true
  where app_private.analytics_link_active(l.inquiry_id,l.learner_id,p_as_of)and l.created_at<=p_as_of and i.recorded_at<=p_as_of and i.observed_at<=p_as_of order by l.learner_id,i.observed_at,i.id
 ),cohort as(select f.*,f.observed_at+make_interval(days=>p_days)window_end from first_touch f where(f.observed_at at time zone'Africa/Cairo')::date between p_from and p_to and(p_campaign is null or f.campaign_id=p_campaign)and(p_source is null or f.attribution=p_source)),
 facts as(select c.*,p.display_name,coalesce(h.history_complete,false)history_complete,coalesce(h.version,1)history_version,att.actual_start_at first_attendance_at,att.occurrence_id first_occurrence_id,
  (select count(*)from app_private.learner_links ll join app_private.lead_inquiries ii on ii.id=ll.inquiry_id where ll.learner_id=c.learner_id and app_private.analytics_link_active(ll.inquiry_id,ll.learner_id,p_as_of)and ll.created_at<=p_as_of and ii.recorded_at<=p_as_of and ii.observed_at>=c.observed_at and ii.observed_at<least(c.window_end,p_as_of+interval'1 microsecond'))interactions,
  exists(select 1 from app_private.enrollments e join app_private.occurrences o on o.id=e.occurrence_id join app_private.offers offer on offer.id=o.offer_id join app_private.quote_acceptances q on q.learner_id=e.learner_id join app_private.quotes quote on quote.id=q.quote_id and quote.enrollment_id=e.id where e.learner_id=c.learner_id and q.accepted_at>=c.observed_at and q.accepted_at<c.window_end and q.accepted_at<=p_as_of and(p_format is null or o.format=p_format)and(p_subject is null or offer.subject_id=p_subject))booked,
  exists(select 1 from finance_private.payment_allocations pa join finance_private.charges ch on ch.id=pa.charge_id left join app_private.enrollments e on e.id=ch.enrollment_id left join app_private.occurrences o on o.id=e.occurrence_id left join app_private.offers offer on offer.id=o.offer_id where ch.learner_id=c.learner_id and pa.recorded_at<=p_as_of and pa.effective_at>=c.observed_at and pa.effective_at<c.window_end and pa.effective_at<=p_as_of and pa.amount_minor>coalesce((select sum(ar.amount_minor)from finance_private.allocation_reversals ar where ar.allocation_id=pa.id and ar.recorded_at<=p_as_of),0)and(p_format is null or o.format=p_format)and(p_subject is null or offer.subject_id=p_subject))paid,
  exists(select 1 from app_private.analytics_attendance(p_as_of)a join app_private.occurrences o on o.id=a.occurrence_id join app_private.offers offer on offer.id=o.offer_id where a.learner_id=c.learner_id and a.attendance='present'and a.attended_seconds>0 and a.actual_start_at>=c.observed_at and a.actual_start_at<c.window_end and(p_format is null or o.format=p_format)and(p_subject is null or offer.subject_id=p_subject))attended
 from cohort c join app_private.learners l on l.id=c.learner_id join app_private.people p on p.id=l.person_id
 left join lateral(select history_complete,version from app_private.learner_history_reviews h where h.learner_id=c.learner_id and h.created_at<=p_as_of order by h.version desc limit 1)h on true
 left join lateral(select a.actual_start_at,a.occurrence_id from app_private.analytics_attendance(p_as_of)a where a.learner_id=c.learner_id and a.attendance='present'and a.attended_seconds>0 order by a.actual_start_at,a.occurrence_id limit 1)att on true)
 select jsonb_build_object('learner_id',learner_id,'learner_name',display_name,'first_inquiry_id',id,'first_inquiry_at',observed_at,'cohort_date',(observed_at at time zone'Africa/Cairo')::date,'attribution',attribution,'campaign_id',campaign_id,'history_version',history_version,'history_status',case when first_attendance_at<observed_at then'returning'when history_complete then'complete'else'unknown'end,'interactions',interactions,'booked',booked,'paid',paid,'attended',attended,'newly_taught',history_complete and coalesce(first_attendance_at>=observed_at and first_attendance_at<window_end,false)and attended and exists(select 1 from app_private.occurrences first_o join app_private.offers first_offer on first_offer.id=first_o.offer_id where first_o.id=first_occurrence_id and(p_format is null or first_o.format=p_format)and(p_subject is null or first_offer.subject_id=p_subject)),'first_attendance_at',first_attendance_at,'first_occurrence_id',first_occurrence_id,'provisional',window_end>p_as_of,'window_end',window_end)from facts
$$;
create or replace function api.get_cohort_report(p_from date,p_to date,p_as_of timestamptz,p_observation_days integer default 30,p_campaign_id uuid default null,p_source text default null,p_format text default null,p_subject_id uuid default null,p_policy_version text default'first_eligible_v1',p_cursor uuid default null,p_limit integer default 25)returns jsonb language plpgsql security definer set search_path='' as $$
declare actor uuid:=app_private.require_actor();rows jsonb;items jsonb;summary jsonb;spends jsonb;amount numeric;covered integer;spend_state text;unlinked bigint;begin
 perform app_private.require_role(actor,'admin');perform finance_private.finance_report_range(p_from,p_to,p_as_of);
 if p_to-p_from>365 or p_observation_days is null or p_observation_days not between 1 and 365 or p_limit is null or p_limit not between 1 and 100 or p_policy_version is distinct from'first_eligible_v1'or(p_source is not null and p_source not in('unknown','verified_campaign','verified_organic'))or(p_format is not null and p_format not in('private','group'))then raise exception'VALIDATION_ERROR';end if;
 select coalesce(jsonb_agg(r order by r->>'learner_id'),'[]')into rows from app_private.analytics_cohort_rows(p_from,p_to,p_as_of,p_observation_days,p_campaign_id,p_source,p_format,p_subject_id)r;
 select jsonb_build_object('learners',count(*),'interactions',coalesce(sum((r->>'interactions')::bigint),0),'booked',count(*)filter(where(r->>'booked')::boolean),'paid',count(*)filter(where(r->>'paid')::boolean),'attended',count(*)filter(where(r->>'attended')::boolean),'newly_taught',count(*)filter(where(r->>'newly_taught')::boolean),'returning',count(*)filter(where r->>'history_status'='returning'),'unknown_history',count(*)filter(where r->>'history_status'='unknown'),'verified_campaign',count(*)filter(where r->>'attribution'='verified_campaign'),'verified_organic',count(*)filter(where r->>'attribution'='verified_organic'),'unknown_source',count(*)filter(where r->>'attribution'='unknown'),'provisional',count(*)filter(where(r->>'provisional')::boolean))into summary from jsonb_array_elements(rows)r;
 select coalesce(jsonb_agg(x.r order by x.r->>'learner_id'),'[]')into items from(select r from jsonb_array_elements(rows)r where p_cursor is null or(r->>'learner_id')::uuid>p_cursor order by r->>'learner_id'limit p_limit)x;
 select count(*)into unlinked from app_private.lead_inquiries i where i.recorded_at<=p_as_of and(i.observed_at at time zone'Africa/Cairo')::date between p_from and p_to and not exists(select 1 from app_private.learner_links l where l.inquiry_id=i.id and l.created_at<=p_as_of and app_private.analytics_link_active(l.inquiry_id,l.learner_id,p_as_of));
 spends:='[]';amount:=null;spend_state:='not_applicable';
 if p_campaign_id is not null then
  select coalesce(jsonb_agg(jsonb_build_object('spend_entry_id',s.id,'from',s.from_date,'to',s.to_date,'amount_minor',coalesce(r.amount_minor,s.amount_minor),'expense_id',s.expense_id,'version',coalesce(r.version,1),'evidence_file_id',coalesce(r.evidence_file_id,s.evidence_file_id))order by s.from_date,s.id),'[]'),sum(coalesce(r.amount_minor,s.amount_minor)),coalesce(sum(s.to_date-s.from_date+1),0)into spends,amount,covered
  from app_private.campaign_spend_entries s left join lateral(select amount_minor,version,evidence_file_id from app_private.campaign_spend_revisions r where r.spend_entry_id=s.id and r.created_at<=p_as_of order by version desc limit 1)r on true where s.campaign_id=p_campaign_id and s.created_at<=p_as_of and s.from_date>=p_from and s.to_date<=p_to;
  if jsonb_array_length(spends)>1000 then raise exception'VALIDATION_ERROR';end if;
  spend_state:=case when covered=0 then'missing'when covered=p_to-p_from+1 then'known'else'partial'end;
 end if;
 return jsonb_build_object('from',p_from,'to',p_to,'as_of',p_as_of,'observation_days',p_observation_days,'time_zone','Africa/Cairo','policy_version',p_policy_version,'grain','learner','summary',summary,'unlinked_inquiries',unlinked,'items',items,'next_cursor',case when jsonb_array_length(items)=p_limit then items->-1->>'learner_id'else null end,'spend',jsonb_build_object('state',spend_state,'amount_minor',case when amount is null then null else finance_private.finance_safe_total(amount)end,'currency','EGP','basis','campaign_calendar_dates','cac_minor',case when spend_state='known'and(summary->>'newly_taught')::bigint>0 and p_format is null and p_subject_id is null and(p_source is null or p_source='verified_campaign')then finance_private.finance_safe_total(round(amount/(summary->>'newly_taught')::numeric))else null end,'entries',spends));
end$$;
create or replace function api.list_analytics_inquiries(p_learner_id uuid default null,p_cursor uuid default null,p_limit integer default 25)returns jsonb language plpgsql security definer set search_path='' as $$declare actor uuid:=app_private.require_actor();items jsonb;begin perform app_private.require_role(actor,'admin');if p_limit is null or p_limit not between 1 and 100 then raise exception'VALIDATION_ERROR';end if;
 select coalesce(jsonb_agg(x.item order by x.id),'[]')into items from(select i.id,jsonb_build_object('inquiry_id',i.id,'source',i.source,'source_event_id',i.source_event_id,'actor_account_id',i.actor_account_id,'observed_at',i.observed_at,'recorded_at',i.recorded_at,'observed_source_token',i.observed_source_token,'attribution',coalesce(r.attribution,'unknown'),'campaign_id',r.campaign_id,'version',coalesce(r.version,1),'links',(select coalesce(jsonb_agg(jsonb_build_object('learner_id',l.learner_id,'active',app_private.analytics_link_active(l.inquiry_id,l.learner_id,now()),'version',coalesce((select max(version)from app_private.learner_link_reviews lr where lr.inquiry_id=l.inquiry_id and lr.learner_id=l.learner_id),1))order by l.learner_id),'[]')from app_private.learner_links l where l.inquiry_id=i.id),'learner_ids',(select coalesce(jsonb_agg(l.learner_id order by l.learner_id),'[]')from app_private.learner_links l where l.inquiry_id=i.id and app_private.analytics_link_active(l.inquiry_id,l.learner_id,now())))item from app_private.lead_inquiries i left join lateral(select a.*from app_private.attribution_revisions a where a.inquiry_id=i.id order by version desc limit 1)r on true where(p_cursor is null or i.id>p_cursor)and(p_learner_id is null or exists(select 1 from app_private.learner_links l where l.inquiry_id=i.id and l.learner_id=p_learner_id and app_private.analytics_link_active(l.inquiry_id,l.learner_id,now())))order by i.id limit p_limit)x;
 return jsonb_build_object('items',items,'next_cursor',case when jsonb_array_length(items)=p_limit then items->-1->>'inquiry_id'else null end);end$$;
create or replace function api.analytics_command(p_name text,p_input jsonb,p_idempotency_key text)returns jsonb language plpgsql security definer set search_path='' as $$
declare actor uuid:=app_private.require_actor();ctx jsonb;resource uuid;v integer:=1;expected integer;allowed text[];inquiry app_private.lead_inquiries%rowtype;campaign app_private.campaigns%rowtype;spend app_private.campaign_spend_entries%rowtype;row record;amount bigint;evidence uuid;from_day date;to_day date;begin
 perform app_private.require_role(actor,'admin');
 allowed:=case p_name when'create_campaign'then array['source','external_campaign_id','name','active_from','active_to'] when'review_attribution'then array['inquiry_id','attribution','campaign_id','evidence_file_id','reason','expected_version'] when'link_inquiry_learner'then array['inquiry_id','learner_id','evidence_file_id','reason'] when'record_learner_history'then array['learner_id','history_complete','evidence_file_id','reason','expected_version'] when'record_campaign_spend'then array['campaign_id','from','to','amount_minor','currency','evidence_file_id','expense_id'] when'correct_campaign_spend'then array['spend_entry_id','amount_minor','reason','evidence_file_id','expected_version']else null end;
 if allowed is null or jsonb_typeof(p_input)is distinct from'object'or p_input-allowed<>'{}'or not(p_input?&allowed)then raise exception'VALIDATION_ERROR';end if;
 ctx:=app_private.booking_begin(actor,p_name,p_input,p_idempotency_key);if ctx->'replay_result'<>'null'::jsonb then return ctx->'replay_result';end if;
 if p_input?'reason'and(p_input->>'reason'is null or length(btrim(p_input->>'reason'))not between 1 and 2000)then raise exception'VALIDATION_ERROR';end if;
 if p_input?'expected_version'then if jsonb_typeof(p_input->'expected_version')<>'number'or(p_input->>'expected_version')!~'^[1-9][0-9]{0,8}$'then raise exception'VALIDATION_ERROR';end if;expected:=(p_input->>'expected_version')::integer;end if;
 if p_input?'evidence_file_id'and p_input->>'evidence_file_id'is not null then evidence:=(p_input->>'evidence_file_id')::uuid;perform app_private.payment_assert_file(evidence,'analytics_evidence','analytics',null,actor);end if;
 if p_name<>'create_campaign'and not(p_name='review_attribution'and p_input->>'attribution'='unknown')and evidence is null then raise exception'VALIDATION_ERROR';end if;
 if p_name='create_campaign'then
  if p_input->>'source'is null or length(btrim(p_input->>'source'))not between 1 and 100 or p_input->>'external_campaign_id'is null or length(btrim(p_input->>'external_campaign_id'))not between 1 and 200 or p_input->>'name'is null or length(btrim(p_input->>'name'))not between 1 and 200 then raise exception'VALIDATION_ERROR';end if;
  from_day:=(p_input->>'active_from')::date;to_day:=(p_input->>'active_to')::date;if from_day is null or to_day is null or not isfinite(from_day)or not isfinite(to_day)or to_day<from_day then raise exception'INVALID_TIME';end if;
  insert into app_private.campaigns(source,external_campaign_id,name,active_from,active_to,actor_id)values(btrim(p_input->>'source'),btrim(p_input->>'external_campaign_id'),btrim(p_input->>'name'),from_day,to_day,actor)returning id into resource;
 elsif p_name in('review_attribution','link_inquiry_learner')then
  perform pg_advisory_xact_lock(hashtextextended('analytics-inquiry:'||(p_input->>'inquiry_id'),0));select * into inquiry from app_private.lead_inquiries where id=(p_input->>'inquiry_id')::uuid;if inquiry.id is null then raise exception'NOT_FOUND';end if;resource:=inquiry.id;
  if p_name='review_attribution'then
   select coalesce(max(version),1)into v from app_private.attribution_revisions where inquiry_id=inquiry.id;if expected is distinct from v then raise exception'VERSION_CONFLICT';end if;
   if p_input->>'attribution'is null or p_input->>'attribution'not in('unknown','verified_organic','verified_campaign')or((p_input->>'attribution'='verified_campaign')<>(p_input->>'campaign_id'is not null))then raise exception'VALIDATION_ERROR';end if;
   if p_input->>'campaign_id'is not null then select * into campaign from app_private.campaigns where id=(p_input->>'campaign_id')::uuid;if campaign.id is null or(inquiry.observed_at at time zone'Africa/Cairo')::date not between campaign.active_from and campaign.active_to then raise exception'STATE_CONFLICT';end if;end if;
   v:=v+1;insert into app_private.attribution_revisions(inquiry_id,version,attribution,campaign_id,evidence_file_id,reason,actor_id)values(inquiry.id,v,p_input->>'attribution',campaign.id,evidence,p_input->>'reason',actor);
   for row in select learner_id from app_private.learner_links where inquiry_id=inquiry.id loop perform app_private.analytics_refresh_attribution(row.learner_id);end loop;
  else
   if not exists(select 1 from app_private.learners where id=(p_input->>'learner_id')::uuid)then raise exception'NOT_FOUND';end if;
   insert into app_private.learner_links(inquiry_id,learner_id,basis,evidence_file_id,actor_id,reason)values(inquiry.id,(p_input->>'learner_id')::uuid,'admin_evidence',evidence,actor,p_input->>'reason')on conflict do nothing;if not app_private.analytics_link_active(inquiry.id,(p_input->>'learner_id')::uuid,now())then insert into app_private.learner_link_reviews(inquiry_id,learner_id,version,active,evidence_file_id,reason,actor_id)select inquiry.id,(p_input->>'learner_id')::uuid,coalesce(max(version),1)+1,true,evidence,p_input->>'reason',actor from app_private.learner_link_reviews where inquiry_id=inquiry.id and learner_id=(p_input->>'learner_id')::uuid;perform app_private.analytics_refresh_attribution((p_input->>'learner_id')::uuid);end if;
  end if;
 elsif p_name='record_learner_history'then
  resource:=(p_input->>'learner_id')::uuid;perform 1 from app_private.learners where id=resource for update;if not found then raise exception'NOT_FOUND';end if;
  if jsonb_typeof(p_input->'history_complete')is distinct from'boolean'then raise exception'VALIDATION_ERROR';end if;select coalesce(max(version),1)into v from app_private.learner_history_reviews where learner_id=resource;if expected is distinct from v then raise exception'VERSION_CONFLICT';end if;v:=v+1;
  insert into app_private.learner_history_reviews(learner_id,version,history_complete,evidence_file_id,reason,actor_id)values(resource,v,(p_input->>'history_complete')::boolean,evidence,p_input->>'reason',actor);
 else
  if jsonb_typeof(p_input->'amount_minor')is distinct from'number'or(p_input->>'amount_minor')!~'^[0-9]+$'or(p_input->>'amount_minor')::numeric>9007199254740991 then raise exception'VALIDATION_ERROR';end if;amount:=(p_input->>'amount_minor')::bigint;
  if p_name='record_campaign_spend'then
   perform pg_advisory_xact_lock(hashtextextended('analytics-campaign:'||(p_input->>'campaign_id'),0));select * into campaign from app_private.campaigns where id=(p_input->>'campaign_id')::uuid;if campaign.id is null then raise exception'NOT_FOUND';end if;
   from_day:=(p_input->>'from')::date;to_day:=(p_input->>'to')::date;if from_day is null or to_day is null or not isfinite(from_day)or not isfinite(to_day)or to_day<from_day or from_day<campaign.active_from or to_day>campaign.active_to or p_input->>'currency'is distinct from'EGP'then raise exception'VALIDATION_ERROR';end if;
   if exists(select 1 from app_private.campaign_spend_entries s where s.campaign_id=campaign.id and daterange(s.from_date,s.to_date,'[]')&&daterange(from_day,to_day,'[]'))then raise exception'STATE_CONFLICT';end if;
   if p_input->>'expense_id'is not null then perform pg_advisory_xact_lock(hashtextextended('analytics-expense:'||(p_input->>'expense_id'),0));perform 1 from finance_private.expenses e where e.id=(p_input->>'expense_id')::uuid and e.currency='EGP'and e.category='marketing'and amount<=e.amount_minor;if not found then raise exception'VALIDATION_ERROR';end if;if exists(select 1 from app_private.campaign_spend_entries where expense_id=(p_input->>'expense_id')::uuid)then raise exception'STATE_CONFLICT';end if;end if;
   insert into app_private.campaign_spend_entries(campaign_id,from_date,to_date,amount_minor,currency,evidence_file_id,expense_id,actor_id)values(campaign.id,from_day,to_day,amount,'EGP',evidence,(p_input->>'expense_id')::uuid,actor)returning id into resource;
  else
   perform pg_advisory_xact_lock(hashtextextended('analytics-spend:'||(p_input->>'spend_entry_id'),0));select * into spend from app_private.campaign_spend_entries where id=(p_input->>'spend_entry_id')::uuid;if spend.id is null then raise exception'NOT_FOUND';end if;resource:=spend.id;select coalesce(max(version),1)into v from app_private.campaign_spend_revisions where spend_entry_id=spend.id;if expected is distinct from v then raise exception'VERSION_CONFLICT';end if;
   if spend.expense_id is not null and amount>(select amount_minor from finance_private.expenses where id=spend.expense_id)then raise exception'VALIDATION_ERROR';end if;v:=v+1;
   insert into app_private.campaign_spend_revisions(spend_entry_id,version,amount_minor,evidence_file_id,reason,actor_id)values(spend.id,v,amount,evidence,p_input->>'reason',actor);
  end if;
 end if;
 return app_private.booking_finish(ctx,resource,v,'{}'::jsonb,'analytics_recorded',jsonb_build_object('resource_id',resource));
end$$;
create function api.review_inquiry_link(p_inquiry_id uuid,p_learner_id uuid,p_active boolean,p_evidence_file_id uuid,p_reason text,p_expected_version integer,p_idempotency_key text)returns jsonb language plpgsql security definer set search_path='' as $$declare actor uuid:=app_private.require_actor();ctx jsonb;v integer;begin
 perform app_private.require_role(actor,'admin');perform app_private.payment_assert_file(p_evidence_file_id,'analytics_evidence','analytics',null,actor);
 if p_active is null or p_reason is null or length(btrim(p_reason))not between 1 and 2000 then raise exception'VALIDATION_ERROR';end if;
 ctx:=app_private.booking_begin(actor,'review_inquiry_link',jsonb_build_object('inquiry_id',p_inquiry_id,'learner_id',p_learner_id,'active',p_active,'evidence_file_id',p_evidence_file_id,'reason',p_reason,'expected_version',p_expected_version),p_idempotency_key);if ctx->'replay_result'<>'null'::jsonb then return ctx->'replay_result';end if;
 perform pg_advisory_xact_lock(hashtextextended('analytics-inquiry:'||p_inquiry_id,0));if not exists(select 1 from app_private.learner_links where inquiry_id=p_inquiry_id and learner_id=p_learner_id)then raise exception'NOT_FOUND';end if;
 select coalesce(max(version),1)into v from app_private.learner_link_reviews where inquiry_id=p_inquiry_id and learner_id=p_learner_id;if v is distinct from p_expected_version then raise exception'VERSION_CONFLICT';end if;v:=v+1;
 insert into app_private.learner_link_reviews(inquiry_id,learner_id,version,active,evidence_file_id,reason,actor_id)values(p_inquiry_id,p_learner_id,v,p_active,p_evidence_file_id,btrim(p_reason),actor);perform app_private.analytics_refresh_attribution(p_learner_id);
 return app_private.booking_finish(ctx,p_inquiry_id,v,'{}'::jsonb,'analytics_recorded',jsonb_build_object('resource_id',p_inquiry_id));
end$$;
do $$declare r record;begin for r in select distinct learner_id from app_private.learner_links where basis='authenticated_self'loop perform app_private.analytics_refresh_attribution(r.learner_id);end loop;end$$;
do $$declare f record;begin for f in select p.oid::regprocedure::text signature,n.nspname from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname in('api','app_private')and p.proname in('analytics_link_active','analytics_refresh_attribution','analytics_source_hook','analytics_cohort_rows','get_cohort_report','list_analytics_inquiries','analytics_command','review_inquiry_link')loop execute format('alter function %s owner to git_tutor_commands',f.signature);execute format('revoke all on function %s from public,anon,authenticated,service_role,git_tutor_worker',f.signature);if f.nspname='api'then execute format('grant execute on function %s to authenticated',f.signature);end if;end loop;end$$;
revoke create on schema api,app_private from git_tutor_commands;
